import os
import shutil
from lxml import etree
try:
    from pkg_resources import resource_filename
except ImportError:
    from importlib.resources import files
from tempfile import NamedTemporaryFile, mkdtemp
from wrapt import decorator


@decorator
def path_to_temp_dir(wrapped, instance, args, kwargs):
    """A decorator for test methods that creates a temporary dir and passes its path as an argument.
    The created dir is later automatically deleted."""
    temp_dir = mkdtemp()
    try:
        return wrapped(temp_dir, *args, **kwargs)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


@decorator
def path_to_temp_file(wrapped, instance, args, kwargs):
    """A test method decorator that creates a temporary file and passes its path as an argument to the decorated
    method. The created file is later automatically deleted.
    Useful for testing functions that create or copy a file.
    """
    temp_file = NamedTemporaryFile(delete=False)
    temp_file.close()
    try:
        return wrapped(temp_file.name, *args, **kwargs)
    finally:
        os.unlink(temp_file.name)


def path_to_temp_copy_of_resource(module_name, relative_path):
    """A test method decorator that creates a temporary file with content equal to given resource and passes its path
    to the decorated method. The created file is later automatically deleted.
    Useful for testing functions that modify a file in place.
    """
    @decorator
    def _wrapper(wrapped, instance, args, kwargs):
        temp_file = NamedTemporaryFile(delete=False)
        temp_file.close()
        try:
            source_path = resource_filename(module_name, relative_path)
        except ImportError:
            source_path = files(module_name) / relative_path
            source_path = str(source_path)
        shutil.copyfile(source_path, temp_file.name)
        try:
            return wrapped(temp_file.name, *args, **kwargs)
        finally:
            os.unlink(temp_file.name)
    return _wrapper


def path_to_resource(module_name, relative_path):
    """A test method decorator that finds the path to given resource and passes it as an argument to the decorated
    method. Basically this is an alternative to pkg_resources.resource_filename(module_name, relative_path), included
    for consistency.
    """
    @decorator
    def _wrapper(wrapped, instance, args, kwargs):
        try:
            resource_path = resource_filename(module_name, relative_path)
        except ImportError:
            resource_path = files(module_name) / relative_path
            resource_path = str(resource_path)
        return wrapped(resource_path, *args, **kwargs)
    return _wrapper


def xml_from_resource(module_name, relative_path):
    """A test method decorator that parses given XML resource using lxml.etree.parse and passes the result as an
    argument to the decorated method. Useful for testing functions that modify XML object trees.
    """
    @decorator
    def _wrapper(wrapped, instance, args, kwargs):
        try:
            resource_path = resource_filename(module_name, relative_path)
        except ImportError:
            resource_path = files(module_name) / relative_path
            resource_path = str(resource_path)
        xml = etree.parse(resource_path)
        return wrapped(xml, *args, **kwargs)
    return _wrapper
